def zone_of(region,sub,city,state=''):
    s=f"{sub or ''} | {city or ''} | {state or ''}".lower()
    for z,core,rx in R.get(region,[]):
        if re.search(rx,s): return z,bool(core)
    return (sub or city or 'Other'),False
